        entries.push(ListEntry::ProjectHeader {
            key: group_key.clone(),
            label,
            highlight_positions: workspace_highlight_positions,
            has_running_threads,
            waiting_thread_count,
            has_notifications: has_thread_notifications || has_terminal_notifications,
            is_active,
            has_threads,
